import{z as l,x as s,o as e,c as o,q as B,j as i,D as a,d as t,s as r,S as n}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"流动性风险计量","description":"","frontmatter":{"title":"流动性风险计量","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/rk-liquidity-measurement.md","filePath":"quant/rk-liquidity-measurement.md","lastUpdated":1791063341000}'),d={name:"quant/rk-liquidity-measurement.md"};function u(C,E,m,h,p,D){const A=s("Mermaid");return e(),o("div",null,[E[2]||(E[2]=B('<h1 id="流动性风险计量" tabindex="-1">流动性风险计量 <a class="header-anchor" href="#流动性风险计量" aria-label="Permalink to &quot;流动性风险计量&quot;">​</a></h1><div class="epigraph"><p>流动性风险有两张面孔：想把仓位换成现金时的市场，和想按时拿到现金时的资金；把两张脸当成一张的机构，在两次危机里各错一次。</p><footer>—— 据 Brunnermeier and Pedersen, *Review of Economic Studies*, 2009；BCBS, *Basel III: The Liquidity Coverage Ratio and liquidity risk monitoring tools*, 2013 整理</footer></div><p><a href="/quant/rk-market-system">上一课</a>把市场风险装进六环流水线：快照、映射、情景、重估、分位数、回测，并规定例外要按环归因。留下一处缺口：整条流水线按中间价计损益，变现成本没有入场。本课把流动性拆成两条线分别计量——市场侧的「退出要花多少」，资金侧的「现金接得上吗」——再讨论两条线如何互相放大。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>中间价 VaR 隐含一个假设：头寸可按标记价退出。市场侧的缺口分两层：外生价差——任何人都付的成本；内生冲击——仓越大，退出把价格压得越低，成本随自己变。资金侧的缺口是现金流错配：保证金追缴、抵押品补足、负债展期都有自己的日程，账面盈利的机构照样死于付不出现金。错法各有典型：用半价差给大仓位计成本，漏掉的主导项是冲击与变现时间；用市场侧指标管资金链，1998 年那种「资产没问题、融资断了」的死法完全不在视野里；反过来只盯现金流，2008 年「能变现的资产突然折价三成」又数不出来。</p><p><span class="marginnote">术语翻译：外生价差是「任何人来卖都要付」的买卖价差，像超市的标价；内生冲击是「你自己卖太多把价砸下去」的部分，像往小池塘里连续倒水——水位被自己的动作改变。小仓位可以只算前者，大仓位的主导项一定是后者。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>市场侧分三档。小仓位按 <a href="/quant/liquidity-adjusted-var">流动性调整 VaR</a> 的口径，把外生价差成本加到中间价 VaR 上；更一致的做法是在每条情景里用可成交价定义损失，三种 VaR 算法都适用。大仓位的主导项换成变现计划：按 <a href="/quant/almgren-chriss">Almgren–Chriss 最优执行</a>的框架，用冲击系数与风险厌恶解出变现时间表，成本是「冲击成本与持有风险的折中」，把这条成本曲线的分位数记作流动性的仓位数额。截面代理用 <a href="/quant/amihud-illiquidity">Amihud 非流动性</a>或价差时间序列做日常监测，债券侧有<a href="/quant/bond-liquidity-trace">债券流动性与 TRACE</a> 的成交口径。资金侧同样分层：现金流梯级表把未来每日的 contractual 流入流出排队，压力参数给出日缺口；监管口径 LCR 要求优质流动性资产覆盖三十天压力净流出，NSFR 要求一年期稳定资金对上所需稳定资金。</p>',8)),(e(),i(n,null,{default:a(()=>[r(A,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E8%A6%81%E8%AE%A1%E9%87%8F%E9%80%80%E5%87%BA%E7%8E%B0%E9%87%91%E6%88%90%E6%9C%AC%EF%BC%8C%E4%BB%93%E4%BD%8D%E8%A7%84%E6%A8%A1%E5%A4%9A%E5%A4%A7%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%20S%5B%22%E5%B0%8F%E4%BB%93%E4%BD%8D%EF%BC%9A%E5%A4%96%E7%94%9F%E4%BB%B7%E5%B7%AE%E5%8A%A0%E9%A1%B9%E7%9A%84%20LVaR%22%5D%0A%20%20Q%20--%3E%20L%5B%22%E5%A4%A7%E4%BB%93%E4%BD%8D%EF%BC%9A%E5%8F%98%E7%8E%B0%E8%AE%A1%E5%88%92%E4%B8%8E%E5%86%B2%E5%87%BB%E6%88%90%E6%9C%AC%22%5D%0A%20%20Q%20--%3E%20MON%5B%22%E6%97%A5%E5%B8%B8%E7%9B%91%E6%B5%8B%EF%BC%9AAmihud%20%E6%88%96%E4%BB%B7%E5%B7%AE%E5%BA%8F%E5%88%97%22%5D%0A%20%20L%20--%3E%20CAP%5B%22%E6%88%90%E6%9C%AC%E6%9B%B2%E7%BA%BF%E7%9A%84%E5%88%86%E4%BD%8D%E6%95%B0%20%3D%20%E4%BB%93%E4%BD%8D%E6%95%B0%E9%A2%9D%22%5D%0A%20%20FUND%5B%22%E8%B5%84%E9%87%91%E4%BE%A7%EF%BC%9A%E7%8E%B0%E9%87%91%E6%B5%81%E6%A2%AF%E7%BA%A7%20%2B%20LCR%2FNSFR%22%5D%20--%3E%20SEP%5B%22%E4%B8%A4%E6%9D%A1%E7%BA%BF%E5%88%86%E5%BC%80%E6%8A%A5%EF%BC%8C%E5%86%8D%E6%9F%A5%E6%8A%B5%E6%8A%BC%E5%93%81%E8%80%A6%E5%90%88%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<p><span class="marginnote">巴塞尔 III 的 LCR 分子是优质流动性资产（一级不打折、二级占比受限），分母是三十天压力情景下的净流出，要求比率 \\(\\ge 100\\%\\)；压力参数按负债类别给流失率、按衍生品状态给抵押品追加。对非银行机构它是类比不是义务，但「三十天现金梯级」的思路通用。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>两条线通过抵押品耦合：价格下跌触发追加保证金，机构被迫变现资产，变现冲击压低价格，再触发更多追缴——<a href="/quant/rc-collateral-funding">抵押品与资金链</a>讲的螺旋在计量上表现为外生与内生项同时恶化。这解释了内生 LVaR 的一个数学后果：变现成本随仓位增长，破坏正齐次性，把加仓的资本收费写成线性会低估集中度。它也决定了退出假设必须统一：监管的流动性期限与内部的 LVaR 用同一套变现时间与冲击参数，否则限额说「三天能走」，资本说「十天才走得完」，两套口径各自合法、合起来失效。</p><p><span class="marginnote">数字实例：某银行 30 天压力净流出预计 80 亿，手持一级优质流动性资产 90 亿，LCR=90/80=112.5%，达标。若市场下跌触发 20 亿保证金追缴用现金支付，分子只剩 70 亿，比率跌到 87.5%——账面盈利一分没少，现金梯级先断了。</span></p>',4)),(e(),i(n,null,{default:a(()=>[r(A,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20POS%5B%22%E5%A4%B4%E5%AF%B8%E4%B8%8E%E9%9B%86%E4%B8%AD%E5%BA%A6%22%5D%20--%3E%20EXO%5B%22%E5%A4%96%E7%94%9F%EF%BC%9A%E4%BB%B7%E5%B7%AE%E6%88%90%E6%9C%AC%22%5D%0A%20%20POS%20--%3E%20END%5B%22%E5%86%85%E7%94%9F%EF%BC%9A%E5%86%B2%E5%87%BB%E4%B8%8E%E5%8F%98%E7%8E%B0%E6%97%B6%E9%97%B4%22%5D%0A%20%20EXO%20--%3E%20LVAR%5B%22%E6%B5%81%E5%8A%A8%E6%80%A7%E8%B0%83%E6%95%B4%E8%AE%A1%E9%87%8F%22%5D%0A%20%20END%20--%3E%20LVAR%0A%20%20CF%5B%22%E7%8E%B0%E9%87%91%E6%B5%81%E6%A2%AF%E7%BA%A7%E4%B8%8E%E6%8A%B5%E6%8A%BC%E5%93%81%22%5D%20--%3E%20GAP%5B%22%E5%8E%8B%E5%8A%9B%E6%97%A5%E7%BC%BA%E5%8F%A3%22%5D%0A%20%20LVAR%20--%3E%20LINK%7B%22%E4%BB%B7%E6%A0%BC%E4%B8%8B%E8%B7%8C%E8%A7%A6%E5%8F%91%E8%BF%BD%E7%BC%B4%3F%22%7D%0A%20%20GAP%20--%3E%20LINK%0A%20%20LINK%20--%3E%7C%22%E6%98%AF%22%7C%20SPIRAL%5B%22%E5%8F%98%E7%8E%B0%E5%8E%8B%E4%BB%B7%EF%BC%8C%E7%BC%BA%E5%8F%A3%E5%86%8D%E6%94%BE%E5%A4%A7%22%5D%0A%20%20SPIRAL%20--%3E%7C%22%E5%8F%8D%E9%A6%88%E5%9B%9E%E5%A4%96%E7%94%9F%E4%B8%8E%E5%86%85%E7%94%9F%E5%8F%82%E6%95%B0%22%7C%20POS%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>外生加项忽略价差与市场的正依赖，把加法当近似可以、当上界不行——那是 <a href="/quant/liquidity-adjusted-var">流动性调整 VaR</a> 课的结论，本课沿用。Amihud 类指标是截面代理，回答「市场贵不贵」，回答不了「我这仓退得出吗」。LCR 与 NSFR 是银行监管口径，基金与自营没有对应义务，但现金流梯级与抵押品驱动的思路必须自己搭。压力参数（流失率、追缴幅度）取自监管校准时是下限，本机构客户结构更挤提时应上调——参数错误是下一类计量课题的入口。</p><p><span class="marginnote">常见误区：把 LCR 达标当成「不会缺钱」。LCR 只看 30 天，压力参数还是监管校准的下限；客户结构更挤提、或 30 天之外藏着悬崖式到期，它都看不见。监管比率是及格线，不是资金风险的全貌。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>流动性计量分市场侧（退出的成本）与资金侧（现金的日程），指标不可互换。</li><li>小仓位用价差加项，大仓位的主导项是冲击与变现时间，用执行框架定退出计划。</li><li>内生成本随仓位增长，破坏正齐次性；集中度收费不能线性外推。</li><li>退出假设要在监管口径与内部口径间统一，否则限额与资本各说各话。</li><li>出处：Bangia, Diebold, Schuermann and Stroughair, 1999；Almgren and Chriss, 2000；Brunnermeier and Pedersen, <em>Review of Economic Studies</em>, 2009；BCBS LCR/NSFR 标准，2013。</li></ul>',5))])}const c=l(d,[["render",u]]);export{_ as __pageData,c as default};
